import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Updating server and clients","description":"","frontmatter":{"pageId":"admins/updating","contentRevision":2},"headers":[],"relativePath":"en/admins/updating.md","filePath":"en/admins/updating.md"}'),o={name:"en/admins/updating.md"};function r(s,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="updating-server-and-clients" tabindex="-1">Updating server and clients <a class="header-anchor" href="#updating-server-and-clients" aria-label="Permalink to &quot;Updating server and clients&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>Read release changes and align server, mod and modpack versions.</li><li>Announce maintenance, end sessions gracefully and create a consistent backup. Record the current version and settings.</li><li>Test the update on a separate data copy. EF migrations apply at startup; keep the old snapshot until verification.</li><li>Replace the server, then update the client mod with the game closed. Rebuild/republish a permitted collection when requirements change.</li><li>Check login, save download/upload, mail and modpack. Reopen access only after successful checks.</li></ol><p>If it fails, stop the new server. Restore a compatible old-server/data-backup set; merely replacing binaries after migration does not guarantee compatibility.</p><h2 id="update-proof" tabindex="-1">Checkpoint and rollback decision <a class="header-anchor" href="#update-proof" aria-label="Permalink to &quot;Checkpoint and rollback decision {#update-proof}&quot;">​</a></h2><p>Before updating, pin binaries/image by version or digest, configuration, collection and a consistent backup. Test migrations, login, save, replay/mail and TLS on a copy. A mod update may require reimporting requirements and rebuilding a permitted ZIP, not just replacing server DLLs.</p><p>If it fails, stop the new version and never let clients use two world copies. Restore a compatible old-binaries/data-backup pair, not just an executable over migrated data. Record operations after the checkpoint; they may need reconciliation.</p><p>Completion requires fresh game login/save acceptance, not merely a running container.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Protocol version changes only for incompatible contracts, but a matching protocol does not remove modpack requirements. Do not update a shared game directory used by someone else&#39;s session. Package publication requires a separate operator decision.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./backup-recovery">Backup and recovery</a></li><li><a href="./../compatibility">Versions and compatibility</a></li><li><a href="./modpacks">Managing modpacks</a></li></ul>',13)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
